<script setup lang="ts">
import { onMounted, ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ElMessage,ElMessageBox } from 'element-plus';import { orderApi,paymentApi } from '@/api';import type { OrderDetail } from '@/types';import { dateTime,money,orderStatusType } from '@/utils'
const route=useRoute(),router=useRouter(),order=ref<OrderDetail>(),paying=ref(false);const load=async()=>order.value=await orderApi.detail(Number(route.params.id));onMounted(load)
const cancel=async()=>{if(!order.value)return;const {value}=await ElMessageBox.prompt('请输入取消原因','取消订单',{inputValidator:v=>!!v||'请输入取消原因'});await orderApi.cancel(order.value.id,value);await load()}
const pay=async()=>{if(!order.value)return;paying.value=true;try{const attempt=await paymentApi.create(order.value.id);await paymentApi.callback(attempt.paymentNo,Number(attempt.amount),true);ElMessage.success('模拟支付成功，库存已确认出库');await load()}finally{paying.value=false}}
</script>
<template><div v-if="order" class="page-container detail"><button class="back" @click="router.back()">← 返回订单</button><section class="hero"><div><el-tag :type="orderStatusType(order.orderStatus)">{{order.orderStatusName}}</el-tag><h1>订单 {{order.orderNo}}</h1><p>关键状态与库存动作均记录在数据库中。</p></div><b>{{money(order.orderAmount)}}</b></section><div class="grid"><main><section class="card"><h2>配送地址</h2><p>{{order.receiverName}} {{order.receiverPhone}}</p><p>{{order.receiverAddress}}</p></section><section class="card"><h2>商品明细</h2><div v-for="item in order.items" :key="item.id" class="line"><span>{{item.medicineName}} × {{item.quantity}}</span><b>{{money(item.subtotalAmount)}}</b></div></section></main><aside><section class="card"><h2>订单时间线</h2><el-timeline><el-timeline-item v-for="log in order.statusLogs" :key="log.id" :timestamp="dateTime(log.createTime)"><b>{{log.afterStatusName}}</b><p>{{log.remark}}</p></el-timeline-item></el-timeline></section><el-button v-if="order.orderStatus==='PENDING_PAYMENT'" type="primary" size="large" :loading="paying" @click="pay">模拟支付</el-button><el-button v-if="['PENDING_REVIEW','PENDING_PAYMENT','PENDING_ACCEPT'].includes(order.orderStatus)" type="danger" plain @click="cancel">取消订单</el-button><p class="notice">模拟支付不连接真实资金渠道。</p></aside></div></div></template>
<style scoped>.back{border:0;background:none;color:#61748d;margin-bottom:16px;cursor:pointer}.hero{display:flex;justify-content:space-between;align-items:center;padding:26px;border-radius:18px;background:linear-gradient(130deg,#0c56a5,#1680f9);color:#fff}.hero h1{margin:10px 0 5px}.hero p{margin:0;color:#d8efff}.hero>b{font-size:28px}.grid{display:grid;grid-template-columns:1fr 340px;gap:18px;margin-top:18px}.card{background:#fff;border:1px solid #e6edf7;border-radius:14px;padding:20px;margin-bottom:16px}.card h2{font-size:16px}.line{display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid #edf1f5}aside>.el-button{width:100%;margin:0 0 10px}.notice{font-size:12px;color:#8794a6;text-align:center}@media(max-width:720px){.grid{grid-template-columns:1fr}}</style>
